INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25169$nota-0076$m25169$, $m25170$Training and Racing with a Power Meter.pdf$m25170$, $m25171$201$m25171$, $m25172$If you tried to interpolate the power you could elicit for 8 minutes... the line of interpolation would indicate approximately 500 watts, while the Power Duration model indicates 380 watts. That's a substantial difference.$m25172$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25173$nota-0076$m25173$, $m25174$Training and Racing with a Power Meter.pdf$m25174$, $m25175$200$m25175$, $m25176$as the duration goes beyond several minutes and approaches an hour, power roughly plateaus. This plateau in the Power Duration Curve roughly corresponds to the functional threshold.$m25176$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25177$nota-0076$m25177$, $m25178$nota-0053$m25178$, $m25179$pre-requisito$m25179$, $m25180$o modelo Potência-Duração é ajustado sobre a Curva de Potência Média Máxima real (nota-0053)$m25180$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25181$nota-0077$m25181$, $m25182$Training and Racing with a Power Meter.pdf$m25182$, $m25183$202$m25183$, $m25184$Pmax is the greatest amount of power that can be generated for a very short period of time with a minimum of one full pedal revolution with both legs. It is essentially a measure of the true maximal power an individual can produce on the bicycle.$m25184$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25185$nota-0077$m25185$, $m25186$Training and Racing with a Power Meter.pdf$m25186$, $m25187$202$m25187$, $m25188$The Pmax metric is a much truer expression of the maximal neuromuscular power a rider can produce, because the influence of fatigue and overlapping energy system contributions are minimized.$m25188$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25189$nota-0077$m25189$, $m25190$nota-0032$m25190$, $m25191$alternativa-a$m25191$, $m25192$Pmax substitui/refina o critério antigo de potência neuromuscular de 5 segundos usado no Power Profile (nota-0032)$m25192$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25193$nota-0078$m25193$, $m25194$Training and Racing with a Power Meter.pdf$m25194$, $m25195$203$m25195$, $m25196$functional reserve capacity (FRC)... is the amount of continuous work that can be performed above FTP until fatigue occurs... FRC is expressed in terms of joules, and the absolute amount of work the rider can perform above FTP, regardless of the time available to perform it.$m25196$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25197$nota-0078$m25197$, $m25198$Training and Racing with a Power Meter.pdf$m25198$, $m25199$204$m25199$, $m25200$let's say an athlete has an FRC equal to 20 kJ (20,000 J)... if the athlete is going to perform a maximal 30-second effort, he or she will be able to sustain 666.7 watts above FTP (20,000 J/30 sec.)... for 120 seconds 166.7 watts above FTP... if the rider's FTP is 300 watts, he or she would be able to sustain 300 + 167 = 467 watts for 120 seconds.$m25200$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25201$nota-0078$m25201$, $m25202$nota-0045$m25202$, $m25203$pre-requisito$m25203$, $m25204$FRC já havia sido introduzida de forma aplicada no Capítulo 5 (nota-0045); esta nota traz a definição formal e a fórmula de cálculo$m25204$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25205$nota-0079$m25205$, $m25206$Training and Racing with a Power Meter.pdf$m25206$, $m25207$205$m25207$, $m25208$mFTP is the power level on the Power Duration Curve at which the curve flattens horizontally.$m25208$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25209$nota-0079$m25209$, $m25210$Training and Racing with a Power Meter.pdf$m25210$, $m25211$206$m25211$, $m25212$The flat point on this curve identified as the mFTP might correspond to a maximal 45-minute effort, or a 60-minute effort, or a 75-minute effort, depending on the individual and his or her fitness. That being said, on average, the mFTP will still be around one hour for most individuals.$m25212$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25213$nota-0079$m25213$, $m25214$nota-0027$m25214$, $m25215$complementa$m25215$, $m25216$outra definição de mFTP (Capítulo 3, nota-0027, focada na janela móvel de 90 dias do WKO4); esta nota (Capítulo 8) define mFTP a partir do ponto de achatamento da curva Potência-Duração$m25216$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25217$nota-0080$m25217$, $m25218$Training and Racing with a Power Meter.pdf$m25218$, $m25219$207$m25219$, $m25220$Time to exhaustion (TTE)... the duration that the mFTP power level can be maintained.$m25220$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25221$nota-0080$m25221$, $m25222$Training and Racing with a Power Meter.pdf$m25222$, $m25223$207$m25223$, $m25224$These two riders have almost exactly the same Pmax (~1,300 watts) and mFTP (~320 watts). The top rider has a TTE of 34:23 while the bottom rider has a TTE of 52:40.$m25224$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25225$nota-0080$m25225$, $m25226$nota-0079$m25226$, $m25227$pre-requisito$m25227$, $m25228$TTE mede a duração de sustentação do mFTP definido na nota-0079$m25228$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25229$nota-0081$m25229$, $m25230$Training and Racing with a Power Meter.pdf$m25230$, $m25231$208$m25231$, $m25232$stamina... is defined as a measure of resistance to fatigue during prolonged-duration, moderate-intensity exercise... it refers to the time an athlete can ride at a sub-FTP level before fatiguing. A stamina score of 100 percent would indicate that a rider would never fatigue, while a score below 50 percent would indicate that the rider fatigues quickly.$m25232$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25233$nota-0081$m25233$, $m25234$Training and Racing with a Power Meter.pdf$m25234$, $m25235$208$m25235$, $m25236$Most riders will exhibit values in the 75 to 85 percent range, and it is useful to observe stamina over time in order to track increasing or decreasing ability to stave off fatigue at sub-FTP power levels.$m25236$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25237$nota-0081$m25237$, $m25238$nota-0079$m25238$, $m25239$complementa$m25239$, $m25240$refere-se à parte da curva Potência-Duração além do mFTP definido na nota-0079 (cauda longa, esforços sub-FTP)$m25240$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m25241$nota-0083$m25241$, $m25242$Training and Racing with a Power Meter.pdf$m25242$, $m25243$220$m25243$, $m25244$Chronic Training Load (CTL)... is calculated as an exponentially weighted moving average of daily TSS (or TRIMP) values, with the default time constant set to 42 days. (In effect, what this means is that your CTL is primarily a function of the training that you have done in the past three months.)$m25244$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25245$nota-0083$m25245$, $m25246$nota-0062$m25246$, $m25247$pre-requisito$m25247$, $m25248$CTL é calculado a partir do TSS diário definido na nota-0062$m25248$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m25249$nota-0083$m25249$, $m25250$nota-0084$m25250$, $m25251$complementa$m25251$, $m25252$junto com ATL (nota-0084), forma a base do TSB (Training Stress Balance)$m25252$)
